/**
 * The worked example's three approaches, per run (arm, repeat index 0/1). Source: README.md "Worked
 * example" (7 shortcut, 4 look-ahead, 1 other) and PHASE_LOG.md Phase 7; matched to runs by reading
 * each diff. tests/unit/data.test.ts re-derives the shortcut and "other" runs from the diffs.
 */
export type Approach = 'shortcut' | 'lookahead' | 'other';
export const APPROACH_INFO: Record<Approach, { name: string; what: string }> = {
  shortcut: { name: 'Shortcut', what: 'Never treat WINDOW as an alias: a one-line change to ALIAS_TOKENS.' },
  lookahead: { name: 'Look-ahead', what: 'Skip the alias only when a window definition follows WINDOW.' },
  other: { name: 'Other', what: 'Treat WINDOW like the ambiguous LIMIT / OFFSET keywords.' },
};
export const FEATURED_APPROACHES: Record<ArmId, [Approach, Approach]> = {
  none: ['shortcut', 'shortcut'],
  prose: ['shortcut', 'other'],
  sensors: ['shortcut', 'shortcut'],
  both: ['lookahead', 'lookahead'],
  handwritten: ['lookahead', 'shortcut'],
  tuned: ['shortcut', 'lookahead'],
};
/** The shortcut line exactly as the agents wrote it (sqlglot/parser.py). */
export const SHORTCUT_LINE = 'ALIAS_TOKENS: t.ClassVar = ID_VAR_TOKENS - {TokenType.WINDOW}';
